import{_ as a,o as s,c as e,a2 as d}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 3 章 我的工作方式：文件、命令与工具","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 3 章 我的工作方式：文件、命令与工具.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 3 章 我的工作方式：文件、命令与工具.md"}'),n={name:"bluebook/第一篇 使用手册：先把我用起来/第 3 章 我的工作方式：文件、命令与工具.md"};function o(i,t,l,r,p,h){return s(),e("div",null,[...t[0]||(t[0]=[d(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 3 章 我的工作方式：文件、命令与工具（易懂版）](../../easy/第3章 我的工作方式：文件、命令与工具（易懂版）.md)</p></div><h1 id="第-3-章-我的工作方式-文件、命令与工具" tabindex="-1">第 3 章 我的工作方式：文件、命令与工具 <a class="header-anchor" href="#第-3-章-我的工作方式-文件、命令与工具" aria-label="Permalink to &quot;第 3 章 我的工作方式：文件、命令与工具&quot;">​</a></h1><blockquote><p>本章目标：完整认识我的&quot;工具箱&quot;——每件工具干什么、什么时候用、安全边界在哪。学完本章，你会知道什么任务能放心交给我，什么操作我会先问你。</p></blockquote><h2 id="_3-1-我的工具箱全景" tabindex="-1">3.1 我的工具箱全景 <a class="header-anchor" href="#_3-1-我的工具箱全景" aria-label="Permalink to &quot;3.1 我的工具箱全景&quot;">​</a></h2><p>我执行任务靠的不是&quot;魔法&quot;，而是一组明确的工具。<strong>知道有什么工具，你才知道能让我干什么</strong>，这是人机协作的基础。</p><h3 id="_3-1-1-工具清单" tabindex="-1">3.1.1 工具清单 <a class="header-anchor" href="#_3-1-1-工具清单" aria-label="Permalink to &quot;3.1.1 工具清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>干什么</th><th>什么时候用</th><th>对应人类动作</th></tr></thead><tbody><tr><td><strong>Read</strong></td><td>读文件内容（带行号）</td><td>看源码、查日志、读配置</td><td>打开文件阅读</td></tr><tr><td><strong>Write</strong></td><td>创建/覆写文件</td><td>新建文档、生成代码</td><td>新建文件</td></tr><tr><td><strong>Edit</strong></td><td>精确替换文件片段</td><td>改一行配置、修一个 bug</td><td>打开编辑器改几行</td></tr><tr><td><strong>Glob</strong></td><td>按文件名/扩展名找文件</td><td>找 <code>**/*.md</code>、<code>*.rs</code></td><td>按名字搜文件</td></tr><tr><td><strong>Grep</strong></td><td>按内容搜索（支持正则）</td><td>搜报错、找函数定义</td><td>全文搜索关键词</td></tr><tr><td><strong>ExecCommand</strong></td><td>执行 shell 命令</td><td>跑测试、装依赖、批量操作</td><td>打开终端敲命令</td></tr><tr><td><strong>Skill</strong></td><td>调用预设专业技能</td><td>提交 commit、评审 PR</td><td>按 SOP 完成专业动作</td></tr><tr><td><strong>Spawn</strong></td><td>开子代理并行干活</td><td>并行调研、分块生成</td><td>叫同事帮忙</td></tr><tr><td><strong>Team</strong></td><td>组建多智能体团队</td><td>大项目多角色协作</td><td>组建项目组</td></tr><tr><td><strong>ToolSearch</strong></td><td>按需加载工具说明</td><td>需要不常用的工具时</td><td>查工具手册</td></tr></tbody></table><h3 id="_3-1-2-工具分工的第一原则" tabindex="-1">3.1.2 工具分工的第一原则 <a class="header-anchor" href="#_3-1-2-工具分工的第一原则" aria-label="Permalink to &quot;3.1.2 工具分工的第一原则&quot;">​</a></h3><blockquote><p><strong>有专用工具就不用裸命令。</strong> 找文件用 Glob，搜内容用 Grep，改文件用 Edit——而不是让我用命令行绕一圈。这既快又安全。</p></blockquote><p>为什么？因为专用工具是&quot;受控的&quot;：</p><ul><li>Glob/Grep 只读不改，不会误伤文件；</li><li>Edit 只改你指定的片段，不会整文件重写；</li><li>而 shell 命令威力大，误操作代价也大。</li></ul><h2 id="_3-2-我生活在工作目录里" tabindex="-1">3.2 我生活在工作目录里 <a class="header-anchor" href="#_3-2-我生活在工作目录里" aria-label="Permalink to &quot;3.2 我生活在工作目录里&quot;">​</a></h2><h3 id="_3-2-1-工作目录是什么" tabindex="-1">3.2.1 工作目录是什么 <a class="header-anchor" href="#_3-2-1-工作目录是什么" aria-label="Permalink to &quot;3.2.1 工作目录是什么&quot;">​</a></h3><p>我的一切文件操作，都发生在<strong>当前工作目录</strong>内（以及你明确指定的路径）。你给我的相对路径，都基于这个目录解析。</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 示例工作目录（MomaWork 会话目录）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\Users\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">86175</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\AppData\\Roaming\\MomaWork\\MomaWork\\conversations\\momawork</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ebf4db3a</span></span></code></pre></div><h3 id="_3-2-2-目录访问规则" tabindex="-1">3.2.2 目录访问规则 <a class="header-anchor" href="#_3-2-2-目录访问规则" aria-label="Permalink to &quot;3.2.2 目录访问规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>做法</th><th>示例</th></tr></thead><tbody><tr><td>访问当前目录内文件</td><td>直接用相对路径</td><td><code>docs/report.md</code></td></tr><tr><td>访问目录外路径</td><td>给绝对路径</td><td><code>D:\\项目\\data\\sales.csv</code></td></tr><tr><td>需要跨多个目录</td><td>说明目录结构再动手</td><td>&quot;项目在 D:\\proj，输出放这里&quot;</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">重要认知</p><p><strong>我看不到你的整个硬盘。</strong> 如果你希望我处理某个文件，但它不在工作目录里，请先把它放进工作目录，或告诉我绝对路径。</p></div><h2 id="_3-3-命令执行-安全铁律" tabindex="-1">3.3 命令执行：安全铁律 <a class="header-anchor" href="#_3-3-命令执行-安全铁律" aria-label="Permalink to &quot;3.3 命令执行：安全铁律&quot;">​</a></h2><p>我能执行命令，但这不代表我会乱来。有三条铁律：</p><h3 id="_3-3-1-铁律一-先读后改" tabindex="-1">3.3.1 铁律一：先读后改 <a class="header-anchor" href="#_3-3-1-铁律一-先读后改" aria-label="Permalink to &quot;3.3.1 铁律一：先读后改&quot;">​</a></h3><p><strong>编辑文件之前，我一定会先 Read，绝不盲改。</strong> 就像医生开刀前必须先看 CT 片：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ 直接改：你都没看内容就改？风险不可控</span></span>
<span class="line"><span>✅ 标准流程：Read → 理解 → Edit → 展示 diff → 让你检查</span></span></code></pre></div><h3 id="_3-3-2-铁律二-危险操作先确认" tabindex="-1">3.3.2 铁律二：危险操作先确认 <a class="header-anchor" href="#_3-3-2-铁律二-危险操作先确认" aria-label="Permalink to &quot;3.3.2 铁律二：危险操作先确认&quot;">​</a></h3><p>以下操作，我会先征得你同意再执行：</p><table tabindex="0"><thead><tr><th>危险等级</th><th>操作类型</th><th>我的做法</th></tr></thead><tbody><tr><td>🔴 不可逆</td><td>删除文件、覆盖已有文件、<code>git push --force</code></td><td><strong>必先确认</strong></td></tr><tr><td>🟡 影响大</td><td>批量改名、大规模重构、安装依赖</td><td>先展示计划</td></tr><tr><td>🟢 安全</td><td>读文件、搜索、跑只读命令</td><td>直接执行</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">如何配合确认机制</p><p><strong>当收到我的确认询问时，请看清再回答。</strong> 特别是涉及&quot;删除&quot;&quot;覆盖&quot;&quot;推送&quot;的确认——回答&quot;是&quot;之前，确认那确实是你想要的操作。</p></div><h3 id="_3-3-3-铁律三-优先专用工具" tabindex="-1">3.3.3 铁律三：优先专用工具 <a class="header-anchor" href="#_3-3-3-铁律三-优先专用工具" aria-label="Permalink to &quot;3.3.3 铁律三：优先专用工具&quot;">​</a></h3><p>能用工具库解决的，不绕 shell。这既是效率，也是安全。</p><h2 id="_3-4-一个完整示例-改-bug-的七步流程" tabindex="-1">3.4 一个完整示例：改 bug 的七步流程 <a class="header-anchor" href="#_3-4-一个完整示例-改-bug-的七步流程" aria-label="Permalink to &quot;3.4 一个完整示例：改 bug 的七步流程&quot;">​</a></h2><p>把前面所有规则串起来，看一次真实的 bug 修复：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：&quot;src/app.py 第 42 行报 KeyError，帮我看看&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我：</span></span>
<span class="line"><span>① Read src/app.py        ← 先看现场（先读后改）</span></span>
<span class="line"><span>② Grep 搜索 key 相关代码  ← 定位问题根源（专用工具）</span></span>
<span class="line"><span>③ Read 关联文件 config    ← 确认数据结构</span></span>
<span class="line"><span>④ Edit 精确修复           ← 最小改动，只改出问题的地方</span></span>
<span class="line"><span>⑤ 展示 diff 给你看        ← 中间产物可检查</span></span>
<span class="line"><span>⑥ 你确认无误</span></span>
<span class="line"><span>⑦ 执行一条命令验证         ← 运行测试确认修复生效</span></span></code></pre></div><p><strong>每一步都有中间产物，你可以随时叫停、检查、回退。这就是&quot;可检查的 AI&quot;。</strong></p><h2 id="_3-5-工具组合模式" tabindex="-1">3.5 工具组合模式 <a class="header-anchor" href="#_3-5-工具组合模式" aria-label="Permalink to &quot;3.5 工具组合模式&quot;">​</a></h2><p>单工具解决小问题，工具组合解决真问题。以下是三种高频组合：</p><h3 id="_3-5-1-组合一-查找定位模式" tabindex="-1">3.5.1 组合一：查找定位模式 <a class="header-anchor" href="#_3-5-1-组合一-查找定位模式" aria-label="Permalink to &quot;3.5.1 组合一：查找定位模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：找不到某段逻辑</span></span>
<span class="line"><span>解法：Grep 搜关键词 → Read 定位文件 → Read 上下文 → 汇报结论</span></span></code></pre></div><h3 id="_3-5-2-组合二-批量处理模式" tabindex="-1">3.5.2 组合二：批量处理模式 <a class="header-anchor" href="#_3-5-2-组合二-批量处理模式" aria-label="Permalink to &quot;3.5.2 组合二：批量处理模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：把 20 个文件统一改格式</span></span>
<span class="line"><span>解法：Glob 列出目标 → Read 抽查几个 → 批量处理（Write/Edit）→ 抽查验证</span></span></code></pre></div><h3 id="_3-5-3-组合三-项目交付模式" tabindex="-1">3.5.3 组合三：项目交付模式 <a class="header-anchor" href="#_3-5-3-组合三-项目交付模式" aria-label="Permalink to &quot;3.5.3 组合三：项目交付模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：完成一个完整小任务</span></span>
<span class="line"><span>解法：Read 需求 → Glob/Grep 盘点资源 → Write 产出 → 验证 → 汇报交付</span></span></code></pre></div><h2 id="_3-6-练习" tabindex="-1">3.6 练习 <a class="header-anchor" href="#_3-6-练习" aria-label="Permalink to &quot;3.6 练习&quot;">​</a></h2><ol><li><strong>实操</strong>：让我用 Glob 找出当前目录下所有 <code>.md</code> 文件，并统计数量。</li><li><strong>实操</strong>：让我用 Grep 搜一个词（比如你的名字），看看搜出什么。</li><li><strong>实操</strong>：给我写一个小文件，然后让我用 Edit 改其中一行，观察我先 Read 再改的流程。</li><li><strong>思考</strong>：以下哪个操作我会先确认？A. 读取配置文件 B. 删除整个 build 目录 C. 搜索报错日志（答案：B）</li></ol><hr><blockquote><p><strong>小结</strong>：我的工作方式 = 一组受控工具 + 三条安全铁律 + 可检查的中间产物。<strong>我越透明，你越放心；你越了解我的工具，越知道什么任务能交给我。</strong> 下一章，我们完成你的第一个真实任务。</p></blockquote>`,45)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
